#!/bin/sh
# Name: Mealie
# Author: KOReader-Mealie
# Icon: data:image/png;base64,
# DontUseFBInk

# Leave a timestamped marker for the KOReader Mealie plugin, which opens
# its menu at startup when the marker is less than two minutes old.
date +%s > /tmp/mealie.autostart
/var/local/kmc/bin/kpm launch koreader --asap
